using Microsoft.Extensions.Logging;

namespace Pragmatic.Logging.Benchmarks.Modules;

/// <summary>
///     The same two methods of the message bus as Pragmatic.Messaging declares them today: generated by
///     Microsoft, written fully qualified for that reason. Instance methods finding the logger in a
///     <c>_logger</c> field, as the bus's do.
/// </summary>
internal sealed partial class MessagingMicrosoftLog(ILogger logger)
{
    private readonly ILogger _logger = logger;

    [Microsoft.Extensions.Logging.LoggerMessage(Level = LogLevel.Debug, Message = MessagingCallSiteLog.PublishingTemplate)]
    public partial void LogPublishing(string messageType, string topic, string transport, string messageId);

    [Microsoft.Extensions.Logging.LoggerMessage(Level = LogLevel.Error, Message = MessagingCallSiteLog.HandlerFailedTemplate)]
    public partial void LogHandlerFailed(string messageName, string handlerName, Exception ex);
}
